package com.tradingplatform.market.websocket;
import com.tradingplatform.paper.PaperTickListener; import java.math.BigDecimal; import java.time.Instant; import java.util.*; import org.slf4j.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Service;
/** Deterministic development stream. It publishes generic MarketTick events only; no broker APIs are involved. */
@Service("mockMarketStreamService")
public class MockMarketStreamService implements MarketStreamService { private static final Logger log=LoggerFactory.getLogger(MockMarketStreamService.class); private final PaperTickListener listener; private final String provider,key; private final long interval; private final List<BigDecimal> prices; private volatile StreamStatus status=StreamStatus.DISCONNECTED; private volatile int cursor;
 public MockMarketStreamService(PaperTickListener listener,@Value("${trading.MARKET_DATA_PROVIDER:mock}")String provider,@Value("${trading.mock.instrument-key:MOCK|NIFTY25000CE}")String key,@Value("${trading.mock.interval-ms:1000}")long interval,@Value("${trading.mock.prices:7.40,7.50,7.80,8.10,7.90}")String sequence){this.listener=listener;this.provider=provider;this.key=key;this.interval=Math.max(100,interval);this.prices=Arrays.stream(sequence.split(",")).map(String::trim).filter(s->!s.isBlank()).map(BigDecimal::new).toList();}
 @Scheduled(fixedDelayString="${trading.mock.interval-ms:1000}") public void emit(){if(!"mock".equalsIgnoreCase(provider)||prices.isEmpty())return;status=StreamStatus.CONNECTED;BigDecimal p=prices.get(cursor++%prices.size());MarketTick tick=new MarketTick(key,Instant.now(),p,BigDecimal.ONE,BigDecimal.valueOf(cursor),p,p,p,p);try{listener.accept(tick);log.debug("mock market tick key={} price={}",key,p);}catch(Exception e){status=StreamStatus.ERROR;log.warn("mock market tick rejected: {}",e.getMessage());}}
 public void connect(){status=StreamStatus.CONNECTED;} public void disconnect(){status=StreamStatus.DISCONNECTED;} public void subscribe(Set<String> keys){connect();} public void unsubscribe(Set<String> keys){} public StreamStatus status(){return status;} }
